def transform(grid):
    # Infer the smallest repeating row-color sequence compatible with full-width
    # horizontal color clues, then extend it over the board.
    h, w = len(grid), len(grid[0])
    clues = {}
    for r, row in enumerate(grid):
        colors = {v for v in row if v != 0}
        if len(colors) == 1 and all(v in colors for v in row):
            clues[r] = next(iter(colors))
    for period in range(1, h + 1):
        vals = {}
        ok = True
        for r, color in clues.items():
            k = r % period
            if k in vals and vals[k] != color:
                ok = False
                break
            vals[k] = color
        if ok and len(vals) == period:
            return [[vals[r % period] for _ in range(w)] for r in range(h)]
    return [row[:] for row in grid]
