def transform(grid):
    h, w = len(grid), len(grid[0])
    # Clue lines can run horizontally (row bands) or diagonally down-right.
    horizontal = {}
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(v == row[0] for v in row):
            horizontal[r] = row[0]
    if horizontal:
        clues = horizontal
        coords = [r for r in clues]
        period_limit = h
        def residue(pos, p):
            return pos % p
    else:
        clues = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    k = c - r
                    if k in clues and clues[k] != color:
                        raise ValueError('inconsistent diagonal clue')
                    clues[k] = color
        coords = list(clues)
        period_limit = min(h, w)
        def residue(pos, p):
            return pos % p
    for p in range(1, period_limit + 1):
        vals = {}
        for pos in coords:
            k = residue(pos, p)
            color = clues[pos]
            if k in vals and vals[k] != color:
                break
            vals[k] = color
        else:
            if len(vals) == p:
                if horizontal:
                    return [[vals[r % p] for _ in range(w)] for r in range(h)]
                return [[vals[(c-r) % p] for c in range(w)] for r in range(h)]
    raise ValueError('could not infer complete periodic pattern')
